// Some portions generated by Claude
import assert from "node:assert/strict";
import test from "node:test";
import { createBatch, loadedStatus, queryLimit, resultCut } from "../../../main/frontend/graph-explorer/load-batches.ts";

// The Graph servlet stops every result at graph-max-result-rows (5,000 by default) without a marker; the page knows
// that cap and must not call such a result complete.
test("a result as long as the server's row cap may be cut, whatever LIMIT the query asks for", () => {
  assert.deepEqual(resultCut(5000, undefined, 5000), { limit: 5000, byServer: true });
  assert.deepEqual(resultCut(5000, 5000, 5000), { limit: 5000, byServer: true });
  assert.deepEqual(resultCut(200, 200, 5000), { limit: 200, byServer: false }, "the row limit the page asked for");
  assert.equal(resultCut(4999, undefined, 5000), null);
  assert.equal(resultCut(5000, undefined, undefined), null, "no known cap");
});

test("a batch the server cut is not complete, even when its LIMIT says it is", () => {
  const query = "CONSTRUCT WHERE { ?s ?p ?o } LIMIT 10000";
  assert.equal(createBatch("Query", "/graph", query, 5000).complete, true, "5,000 of a LIMIT 10000 looks complete");
  const cut = createBatch("Query", "/graph", query, 5000, resultCut(5000, undefined, 5000));
  assert.deepEqual([cut.limit, cut.complete], [5000, false]);
  assert.equal(createBatch("Query", "/graph", query, 12, null).complete, true);
});

test("the status says when a result was cut, and by whom", () => {
  assert.equal(loadedStatus(1, null, 12.4), "Loaded 1 statement in 12 ms.");
  assert.equal(loadedStatus(4200, null, 80), `Loaded ${(4200).toLocaleString()} statements in 80 ms.`);
  assert.equal(loadedStatus(200, { limit: 200, byServer: false }, 5), "Loaded the first 200 statements; the query has more.");
  assert.equal(
    loadedStatus(5000, { limit: 5000, byServer: true }, 5),
    `Loaded the first ${(5000).toLocaleString()} statements: the server sends at most ${(5000).toLocaleString()} rows for a query, so the result may be cut. Page through it with LIMIT and OFFSET.`,
  );
});

test("the server's word on a cut result wins over guessing from the row count", () => {
  assert.equal(resultCut(5000, undefined, 5000, false), null, "exactly the server's cap, and nothing more");
  assert.equal(resultCut(200, 200, 5000, false), null, "exactly the row limit the page asked for");
  assert.deepEqual(resultCut(5000, undefined, 5000, true), { limit: 5000, byServer: true });
  assert.deepEqual(resultCut(200, 200, 5000, true), { limit: 200, byServer: false });
  assert.deepEqual(resultCut(5000, undefined, 5000), { limit: 5000, byServer: true }, "a server that does not say");
});

test("a query's LIMIT is its outermost one, not a subquery's, a comment's or a string's", () => {
  assert.equal(queryLimit("SELECT ?s ?p ?o { { SELECT ?s { ?s ?p ?o } LIMIT 10 } ?s ?p ?o }"), null);
  assert.equal(queryLimit('SELECT * { ?s ?p "} LIMIT 3" } # LIMIT 4\nLIMIT 50'), 50);
  assert.equal(queryLimit("SELECT * { { SELECT * { ?s ?p ?o } LIMIT 5 } } limit 20 OFFSET 3"), 20);
  assert.equal(queryLimit("CONSTRUCT WHERE { ?s <http://example.org/a#LIMIT> ?o } LIMIT 10000"), 10000);
  assert.equal(queryLimit("CONSTRUCT WHERE { ?s ?p ?o }"), null);
});
